initJs:
function(container, apiUrl, tables) {
  let currentOrderData = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // テーブルインデックスの定義
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const DEMAND_FORECAST_TABLE = 9;
  const ORDER_TABLE = 10;

  // 初期化処理
  async function initialize() {
    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    container.querySelector('#order-date').value = today;

    // データ読み込み
    await loadInitialData();

    // イベントリスナー設定
    setupEventListeners();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      storeData = await window.aivicApi.list(STORE_TABLE) || [];
      productData = await window.aivicApi.list(PRODUCT_TABLE) || [];
      demandForecastData = await window.aivicApi.list(DEMAND_FORECAST_TABLE) || [];

      populateStoreSelect();
      populateCategoryFilter();
      renderOrderTable([]);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を設定
  function populateStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

    storeData.filter(store => store.有効フラグ).forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = `${store.店舗コード} - ${store.店舗名}`;
      storeSelect.appendChild(option);
    });
  }

  // カテゴリフィルター設定
  function populateCategoryFilter() {
    const categoryFilter = container.querySelector('#category-filter');
    categoryFilter.innerHTML = '<option value="">全てのカテゴリ</option>';

    const categories = [...new Set(productData.map(p => p.商品カテゴリID))];
    categories.forEach(categoryId => {
      if (categoryId) {
        const option = document.createElement('option');
        option.value = categoryId;
        option.textContent = `カテゴリ ${categoryId}`;
        categoryFilter.appendChild(option);
      }
    });
  }

  // 発注テーブル描画
  function renderOrderTable(orderItems) {
    const tbody = container.querySelector('#order-table-body');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!orderItems || orderItems.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');

    tbody.innerHTML = orderItems.map(item => {
      const product = productData.find(p => p.商品ID === item.商品ID) || {};
      const forecast = demandForecastData.find(f => f.商品ID === item.商品ID && f.店舗ID === item.店舗ID) || {};

      return `
        <tr data-product-id="${item.商品ID}">
          <td><input type="checkbox" class="item-checkbox" data-product-id="${item.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${forecast.予測数量 || 0}</td>
          <td>${forecast.推奨発注数量 || 0}</td>
          <td>${item.現在在庫数量 || 0}</td>
          <td><input type="number" class="input order-quantity" data-product-id="${item.商品ID}" value="${forecast.推奨発注数量 || 0}" min="0" style="width: 80px;"></td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td class="order-amount" data-product-id="${item.商品ID}">¥0</td>
          <td><button class="action-btn secondary single-order-btn" data-product-id="${item.商品ID}">個別発注</button></td>
        </tr>
      `;
    }).join('');

    // 金額計算
    updateAllAmounts();
  }

  // 全ての金額を更新
  function updateAllAmounts() {
    const quantityInputs = container.querySelectorAll('.order-quantity');
    quantityInputs.forEach(input => {
      updateOrderAmount(input.dataset.productId);
    });
    updateSummary();
  }

  // 個別商品の発注金額を更新
  function updateOrderAmount(productId) {
    const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
    const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
    const product = productData.find(p => p.商品ID === productId);

    if (quantityInput && amountCell && product) {
      const quantity = parseInt(quantityInput.value) || 0;
      const unitPrice = product.単価 || 0;
      const amount = quantity * unitPrice;
      amountCell.textContent = `¥${amount.toLocaleString()}`;
    }
  }

  // サマリー更新
  function updateSummary() {
    const checkboxes = container.querySelectorAll('.item-checkbox:checked');
    const summaryDiv = container.querySelector('#order-summary');

    if (checkboxes.length === 0) {
      summaryDiv.style.display = 'none';
      container.querySelector('#btn-bulk-order').disabled = true;
      return;
    }

    summaryDiv.style.display = 'block';
    container.querySelector('#btn-bulk-order').disabled = false;

    let totalQuantity = 0;
    let totalAmount = 0;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
      const product = productData.find(p => p.商品ID === productId);

      if (quantityInput && product) {
        const quantity = parseInt(quantityInput.value) || 0;
        const unitPrice = product.単価 || 0;
        totalQuantity += quantity;
        totalAmount += quantity * unitPrice;
      }
    });

    container.querySelector('#selected-count').textContent = checkboxes.length;
    container.querySelector('#total-quantity').textContent = totalQuantity.toLocaleString();
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
  }

  // 発注データ検索・表示更新
  async function searchOrderData() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryId = container.querySelector('#category-filter').value;

    if (!storeId) {
      renderOrderTable([]);
      return;
    }

    // 選択された店舗と日付に基づいて発注対象商品を生成
    let filteredProducts = productData.filter(p => p.有効フラグ && p.AI予測対象フラグ);

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    const orderItems = filteredProducts.map(product => ({
      商品ID: product.商品ID,
      店舗ID: storeId,
      現在在庫数量: Math.floor(Math.random() * 100) // サンプル在庫数
    }));

    currentOrderData = orderItems;
    renderOrderTable(orderItems);
  }

  // バリデーション
  function validateOrderData(orderItems) {
    const errors = [];
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      errors.push('店舗を選択してください');
    }

    if (!orderDate) {
      errors.push('発注日付を選択してください');
    } else {
      const today = new Date().toISOString().split('T')[0];
      if (orderDate < today) {
        errors.push('発注日付は本日以降の日付を選択してください');
      }
    }

    orderItems.forEach((item, index) => {
      const quantityInput = container.querySelector(`.order-quantity[data-product-id="${item.productId}"]`);
      if (quantityInput) {
        const quantity = quantityInput.value;

        if (!quantity || quantity === '') {
          errors.push(`商品${index + 1}: 発注数量を入力してください`);
        } else if (isNaN(quantity) || !Number.isInteger(parseFloat(quantity))) {
          errors.push(`商品${index + 1}: 発注数量は整数を入力してください`);
        } else if (parseFloat(quantity) <= 0) {
          errors.push(`商品${index + 1}: 発注数量は1以上の値を入力してください`);
        } else if (parseFloat(quantity) > 99999) {
          errors.push(`商品${index + 1}: 発注数量は99999以下で入力してください`);
        }
      }
    });

    return errors;
  }

  // 発注確認モーダル表示
  function showOrderConfirmModal(orderItems) {
    const modal = container.querySelector('#order-confirm-modal');
    const content = container.querySelector('#confirm-content');

    const storeSelect = container.querySelector('#store-select');
    const storeName = storeSelect.options[storeSelect.selectedIndex].text;
    const orderDate = container.querySelector('#order-date').value;

    let totalAmount = 0;
    const itemsHtml = orderItems.map(item => {
      const product = productData.find(p => p.商品ID === item.productId);
      const quantity = parseInt(item.quantity);
      const unitPrice = product.単価 || 0;
      const amount = quantity * unitPrice;
      totalAmount += amount;

      return `
        <tr>
          <td>${product.商品コード}</td>
          <td>${product.商品名}</td>
          <td>${quantity}</td>
          <td>¥${unitPrice.toLocaleString()}</td>
          <td>¥${amount.toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    content.innerHTML = `
      <div style="margin-bottom: 15px;">
        <strong>店舗:</strong> ${storeName}<br>
        <strong>発注日:</strong> ${orderDate}
      </div>
      <table style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr style="background: var(--bg-main);">
            <th style="padding: 8px; border: 1px solid var(--border);">商品コード</th>
            <th style="padding: 8px; border: 1px solid var(--border);">商品名</th>
            <th style="padding: 8px; border: 1px solid var(--border);">数量</th>
            <th style="padding: 8px; border: 1px solid var(--border);">単価</th>
            <th style="padding: 8px; border: 1px solid var(--border);">金額</th>
          </tr>
        </thead>
        <tbody>
          ${itemsHtml}
        </tbody>
      </table>
      <div style="margin-top: 15px; text-align: right;">
        <strong style="font-size: 1.2em; color: var(--primary);">合計金額: ¥${totalAmount.toLocaleString()}</strong>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder(orderItems) {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    try {
      for (const item of orderItems) {
        const product = productData.find(p => p.商品ID === item.productId);
        const quantity = parseInt(item.quantity);
        const unitPrice = product.単価 || 0;

        const orderData = {
          店舗ID: storeId,
          商品ID: item.productId,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
          発注数量: quantity,
          発注単価: unitPrice,
          発注金額: quantity * unitPrice,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID || 'default-supplier',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      alert('発注が正常に実行されました');
      container.querySelector('#order-confirm-modal').classList.add('hidden');

      // チェックボックスをクリア
      container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = false);
      container.querySelector('#select-all').checked = false;
      updateSummary();

    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 表示更新ボタン
    container.querySelector('#btn-search').addEventListener('click', searchOrderData);

    // 店舗選択変更
    container.querySelector('#store-select').addEventListener('change', searchOrderData);

    // カテゴリフィルター変更
    container.querySelector('#category-filter').addEventListener('change', searchOrderData);

    // 全選択チェックボックス
    container.querySelector('#select-all').addEventListener('change', function() {
      const checkboxes = container.querySelectorAll('.item-checkbox');
      checkboxes.forEach(cb => cb.checked = this.checked);
      updateSummary();
    });

    // 発注数量変更
    container.addEventListener('input', function(e) {
      if (e.target.classList.contains('order-quantity')) {
        updateOrderAmount(e.target.dataset.productId);
        updateSummary();
      }
    });

    // チェックボックス変更
    container.addEventListener('change', function(e) {
      if (e.target.classList.contains('item-checkbox')) {
        updateSummary();

        // 全選択チェックボックスの状態更新
        const allCheckboxes = container.querySelectorAll('.item-checkbox');
        const checkedCheckboxes = container.querySelectorAll('.item-checkbox:checked');
        const selectAllCheckbox = container.querySelector('#select-all');

        if (checkedCheckboxes.length === 0) {
          selectAllCheckbox.indeterminate = false;
          selectAllCheckbox.checked = false;
        } else if (checkedCheckboxes.length === allCheckboxes.length) {
          selectAllCheckbox.indeterminate = false;
          selectAllCheckbox.checked = true;
        } else {
          selectAllCheckbox.indeterminate = true;
        }
      }
    });

    // まとめて発注実行ボタン
    container.querySelector('#btn-bulk-order').addEventListener('click', function() {
      const checkedBoxes = container.querySelectorAll('.item-checkbox:checked');
      const orderItems = Array.from(checkedBoxes).map(cb => {
        const productId = cb.dataset.productId;
        const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
        return {
          productId: productId,
          quantity: quantityInput.value
        };
      });

      const errors = validateOrderData(orderItems);
      if (errors.length > 0) {
        alert(errors.join('\n'));
        return;
      }

      showOrderConfirmModal(orderItems);
    });

    // 個別発注ボタン
    container.addEventListener('click', function(e) {
      if (e.target.classList.contains('single-order-btn')) {
        const productId = e.target.dataset.productId;
        const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);

        const orderItems = [{
          productId: productId,
          quantity: quantityInput.value
        }];

        const errors = validateOrderData(orderItems);
        if (errors.length > 0) {
          alert(errors.join('\n'));
          return;
        }

        showOrderConfirmModal(orderItems);
      }
    });

    // モーダル操作
    container.querySelector('#btn-cancel-order').addEventListener('click', function() {
      container.querySelector('#order-confirm-modal').classList.add('hidden');
    });

    container.querySelector('#btn-execute-order').addEventListener('click', function() {
      const checkedBoxes = container.querySelectorAll('.item-checkbox:checked');
      let orderItems;

      if (checkedBoxes.length > 0) {
        // まとめて発注の場合
        orderItems = Array.from(checkedBoxes).map(cb => {
          const productId = cb.dataset.productId;
          const quantityInput = container.querySelector(`.order-quantity[data-product-id="${productId}"]`);
          return {
            productId: productId,
            quantity: quantityInput.value
          };
        });
      } else {
        // 個別発注の場合（モーダルが開かれた商品）
        const modal = container.querySelector('#order-confirm-modal');
        const productRows = modal.querySelectorAll('tbody tr');
        orderItems = Array.from(productRows).map(row => {
          const cells = row.querySelectorAll('td');
          const productCode = cells[0].textContent;
          const product = productData.find(p => p.商品コード === productCode);
          const quantity = cells[2].textContent;
          return {
            productId: product.商品ID,
            quantity: quantity
          };
        });
      }

      executeOrder(orderItems);
    });

    // モーダル背景クリックで閉じる
    container.querySelector('#order-confirm-modal').addEventListener('click', function(e) {
      if (e.target === this) {
        this.classList.add('hidden');
      }
    });
  }

  // 初期化実行
  initialize();
}
